/**
 * Represents context information for a specific Component API method invocation.
 */
declare type CallInfo = {
    /**
     * The component context of the calling component entry point.
     *
     * @remarks
     * This context be used to distinguish API usage based on the calling component and entry point.
     */
    callerContext: ComponentContext;
    /**
     * Retains the remote callbacks for this specific API method invocation, so that they can be used after the API method has finished executing.
     *
     * @remarks
     * IMPORTANT NOTE: You need to call this function before the Promise returned by your API method resolves.
     * The safest approach is to call this function on the first line of your API method implementation.
     *
     * You only need to call this function if you want to use any callbacks passed by the caller in the parameters of the API method after the API method has finished executing.
     *
     * For example, if you have an API method to register a menu item, and that menu item includes an action callback that you want to invoke later on, you need to retain the callbacks for every invocation of your API method.
     *
     * If you call this function, you also need to dispose of the callbacks again using the returned {@link DisposeCallbacks} function.
     *
     * In the 'register menu item' example, you would store the {@link DisposeCallbacks} function with the registered menu item and then call it when the menu item is deregistered again.
     *
     * @returns a {@link DisposeCallbacks} function that should be called to dispose the remote callbacks when they are no longer necessary.
     */
    retainCallbacks(): DisposeCallbacks;
};

