/**
 * This type is used to make sure that methods implementing the
 * APIs are called with a `CallInfo` as the first argument.
 *
 * Public interface of the APIs should declare methods as they are intended to be used,
 * while the implementation should receive the `CallInfo` as the first argument,
 * which is being injected by the component framework.
 *
 * @example
 * // Your API interface should look like this:
 * interface IMyApi extends IComponentApi {
 *     myMethod(arg1: string, arg2: number): Promise<void>;
 * }
 *
 * // While its implementation should be aware of the first argument being a `CallInfo`:
 * class MyApi extends ComponentApiBase implements ContextAwareApi<IMyApi> {
 *     myMethod(callInfo: CallInfo, arg1: string, arg2: number): Promise<void> {
 *         // Implementation goes here...
 *     }
 * }
 */
declare type ContextAwareApi<TApi extends IComponentApi> = {
    [K in keyof TApi]: K extends keyof IEventManager<{}> ? TApi[K] : TApi[K] extends (...args: infer TArgs) => infer TReturn ? TReturn extends Promise<unknown> ? (callInfo: CallInfo, ...args: TArgs) => TReturn : "Error in Component API implementation: methods must return a Promise" : TApi[K];
};

