/** API for passing messages between different entry points of a component */
export declare interface IMessagePassingApi extends IComponentApi {
    _apiId: "mendix.MessagePassingApi";
    /**
     * Broadcasts a message to other entry points that have registered message handlers.
     * @param message Message that will be sent to other entry points, can be any type.
     * @param onResponse If provided, this function will be called for the *first* entry
     *                   point that calls {@link IMessagePassingApi.sendResponse} with the messageId of the sent message.
     *                   Note that this function will be called at most once, so if you are expecting multiple responses,
     *                   you should register a message handler instead.
     */
    sendMessage<TMessageData, TResponseData>(message: TMessageData, onResponse?: ResponseHandler<TResponseData>): Promise<void>;
    /**
     * Registers a message handler for messages sent to this entry point.
     * Note that this handler will only receive messages sent from other entry points of the same component,
     * and will never see its own messages. Handler will react only to messages that are sent after the handler is registered.
     * @param onMessage Function that will be called when a message is received.
     */
    addMessageHandler<TMessageData>(onMessage: MessageHandler<TMessageData>): Promise<HandlerReference>;
    /**
     * Removes a registered message handler. The handler will no longer receive messages and will release any resources it was using.
     * @param handlerReference The reference to the handler that was returned when the handler was registered.
     * @returns True if the handler was successfully removed, false if no handler with the given reference was found.
     */
    removeMessageHandler(handlerReference: HandlerReference): Promise<boolean>;
    /**
     * Sends a response to a message. It will invoke the `onResponse` callback that was passed to the `sendMessage` method.
     * @param messageId ID of the message to which the response is being sent. ID is obtained from the `MessageInfo` object in handlers.
     * @param response Response that will be sent back to the sender of the message.
     *                 Make sure that the type of the response matches the type expected by the `onResponse` callback.
     * @returns True if the response was successfully sent, false if no message with ID was found or answer was already sent.
     */
    sendResponse<TResponseData>(messageId: string, response: TResponseData): Promise<boolean>;
}

