/** Only action in this type. No submenus are allowed for an executable menu. */
declare type OnlyAction<TActionArg extends ActionArgument> = {
    /** The action that will be executed when the menu item is selected. Cannot be comined with submenus. */
    action: undefined extends TActionArg ? () => Promise<void> : (arg: TActionArg) => Promise<void>;
    /** The children menus of this menu. Cannot be combined with action, so it is set to never here. */
    subMenus?: never;
};

/** Only sub menus in this type. If the menu is a parent menu, it cannot be actionable.
 *  Note that the type argument is setup so that all menus in the hierarchy
 *  must use the same action argument type.
 */
declare type OnlySubMenus<TActionArg extends ActionArgument> = {
    /** The action that will be executed when the menu item is selected. Cannot be comined with submenus, so it is set to never here. */
    action?: never;
    /** The children menus of this menu. Cannot be combined with action. */
    subMenus: Menu<TActionArg>[];
};

/**
 * The operation to apply to the model.
 */
declare type Operation = CreateElementOperation | RemoveElementOperation | InsertElementOperation | RemoveValueOperation | InsertValueOperation | SetPropertyOperation;

declare interface OperationBase {
    /**
     * The type of the operation.
     */
    type: string;
}

